-- Check reportcompliance and dataqualityvalue ranges
SELECT MIN(reportcompliance), MAX(reportcompliance), AVG(reportcompliance) FROM coordinationandevaluation;
SELECT MIN(dataqualityvalue), MAX(dataqualityvalue), AVG(dataqualityvalue) FROM coordinationandevaluation;

-- Check if there's any other table or view with a score column
SELECT table_name, column_name FROM information_schema.columns 
WHERE column_name LIKE '%score%' OR column_name LIKE '%rating%' OR column_name LIKE '%performance%';
